head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > getCDataNodeValue]<br/>XML Element 노드의 CDATA 섹션 값을 반환합니다.",
    "validation" : [
        "element(필수) 파라미터로 CDATA 값을 조회할 XML Element 노드를 설정할 수 있어야 합니다.",
        "CDATA 노드의 값을 반환해야 합니다.",
        "CDATA 노드가 없으면 null 을 반환해야 합니다.",
        "CDATA 노드가 여러 개인 경우 마지막 CDATA 노드의 값만 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getCDataNodeValue_onclick = function () {
    let testCase = par_testCase.getValue();
    var xmlStr, node, result;

    // CDATA 마커를 문자열 결합으로 생성 (외부 CDATA 섹션과 충돌 방지)
    var cdataOpen = '<![CDATA' + '[';
    var cdataClose = ']' + ']>';

    if (testCase === 'single') {
        xmlStr = '<root><item>' + cdataOpen + '<b>Bold Text</b>' + cdataClose + '</item></root>';
        var doc = WebSquare.xml.parse(xmlStr);
        node = WebSquare.xml.findNode(doc, "root/item");
        result = WebSquare.xml.getCDataNodeValue(node);
        wf_body_bottom.getObj("scwin").setReturnValue("CDATA 1개: getCDataNodeValue(item)");
    } else if (testCase === 'multiple') {
        xmlStr = '<root><item>' + cdataOpen + 'first' + cdataClose + cdataOpen + 'last' + cdataClose + '</item></root>';
        var doc = WebSquare.xml.parse(xmlStr);
        node = WebSquare.xml.findNode(doc, "root/item");
        result = WebSquare.xml.getCDataNodeValue(node);
        wf_body_bottom.getObj("scwin").setReturnValue("CDATA 여러개: getCDataNodeValue(item)");
    } else if (testCase === 'none') {
        xmlStr = '<root><item>plain text</item></root>';
        var doc = WebSquare.xml.parse(xmlStr);
        node = WebSquare.xml.findNode(doc, "root/item");
        result = WebSquare.xml.getCDataNodeValue(node);
        wf_body_bottom.getObj("scwin").setReturnValue("CDATA 없음: getCDataNodeValue(item) → null");
    }

    wf_body_bottom.getObj("scwin").setReturnValue("결과 : " + result);
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);
}
